  SELECT v.id, 'bk-95898cdf13', v.a, v.b, v.label, v.page, v.sem FROM (VALUES
  ('1fe35e8c-30a6-5943-a10b-1147103deae3','24657550-b5de-517d-9c16-ab3fb2387a37','7edb9939-a8e8-5e3a-bd4e-f840c9f82d04','부부다',1,'{"version": 2, "direction": "undirected", "kind": "family", "relation_key": "marriage", "summary": "박영민과 이몽란은 부부이며, 이몽란은 좌장 박영민의 부인이다.", "assertion_status": "fact", "temporal_scope": "ongoing", "state": "active", "evidence": {"source_page": 1, "quote": "홍(洪)\n• 좌장 부인 해왕좌 배우 이몽란(李夢蘭, 24) ......", "start_char": 752, "end_char": 791}, "verification": {"check": "confirmed", "reasons": [], "runs_agreed": 2}}'::jsonb),
  ('1d793418-6e9d-5923-a7a9-654a4e36d908','7edb9939-a8e8-5e3a-bd4e-f840c9f82d04','e0ff01ac-0ddb-5f99-be46-3ea6c4799011','친구다',1,'{"version": 2, "direction": "undirected", "kind": "social", "relation_key": "friendship", "summary": "박영민과 유불란은 친구 사이다.", "assertion_status": "fact", "temporal_scope": "ongoing", "state": "active", "evidence": {"source_page": 1, "quote": "유불란\n• 그 외 박영민 댁의 식모 두 사람, 경관 너댓 명\n탐정극 『가상범인』은 좌장의 친구요 탐정 소설계의 명성인 유불란 씨가 저번 세상을 놀라게 한 본 해왕좌의 좌장 박영민 씨 살해사건을 취재하여 친히 원작한 것이다.", "start_char": 920, "end_char": 1044}, "verification": {"check": "confirmed", "reasons": [], "runs_agreed": 2}}'::jsonb),
  ('76a8ff7c-1edc-52f3-aa30-806e2347ba06','24657550-b5de-517d-9c16-ab3fb2387a37','2d8ecb4c-a8d5-5d91-8556-927ffe42e697','사랑한다',6,'{"version": 2, "direction": "b_to_a", "kind": "social", "relation_key": "affection", "summary": "나용귀는 이몽란을 사랑하고 있다고 주장한다.", "assertion_status": "claim", "temporal_scope": "ongoing", "state": "active", "evidence": {"source_page": 6, "quote": ":다섯째로 나용귀의 진술. “나도 두 분의 음성을 똑똑히 들었소이다. 나는 좌장의 뒤를 따라 화장실에 내려간 후 소변을 보고는 뒤뜰에 나아가 잠시 동안 바람을 쏘이면서 좌장이 부인께 준 모욕의 말을 가만히 생각해 보았습니다. 왜 그랬느냐 말씀입니까? 나는 부인을 사랑하고 있습니다.”\n:여섯째로 이몽란의 진술.", "start_char": 43, "end_char": 216}, "attribution": "나용귀", "change_evidence": {"source_page": 6, "quote": ":다섯째로 나용귀의 진술. “나도 두 분의 음성을 똑똑히 들었소이다. 나는 좌장의 뒤를 따라 화장실에 내려간 후 소변을 보고는 뒤뜰에 나아가 잠시 동안 바람을 쏘이면서 좌장이 부인께 준 모욕의 말을 가만히 생각해 보았습니다. 왜 그랬느냐 말씀입니까? 나는 부인을 사랑하고 있습니다.”\n:여섯째로 이몽란의 진술.", "start_char": 43, "end_char": 216}, "verification": {"check": "needs_review", "reasons": ["change_needs_review"], "runs_agreed": 2}}'::jsonb),
  ('b7b060cb-1dc7-5704-a3e2-fd0987683160','24657550-b5de-517d-9c16-ab3fb2387a37','e0ff01ac-0ddb-5f99-be46-3ea6c4799011','사랑한다',6,'{"version": 2, "direction": "a_to_b", "kind": "social", "relation_key": "affection", "summary": "이몽란은 유불란을 사모하고 있다고 주장한다.", "assertion_status": "claim", "temporal_scope": "ongoing", "state": "active", "evidence": {"source_page": 6, "quote": "“나도 두 분의 음성을 똑똑히 들었소이다. 나는 좌장의 뒤를 따라 화장실에 내려간 후 소변을 보고는 뒤뜰에 나아가 잠시 동안 바람을 쏘이면서 좌장이 부인께 준 모욕의 말을 가만히 생각해 보았습니다. 왜 그랬느냐 말씀입니까? 나는 부인을 사랑하고 있습니다.”\n:여섯째로 이몽란의 진술. “저는 뭐가 뭐인지 전연 알 수 없어요. 참말로 이상한 일입니다. 저는 안방에 내려와서 —침방과 서재 사이에는 부엌과 넓은 두 칸 대청이 끼어 있다— 저도 여성이요, 배우인 이상 얼굴에 대한 자존심이 있어요. 주인이 함부로 던진 모욕의 말을 얼마나 원망했을까요! 그래 분한 마음을 참아가면서 이불을 폭 쓰고 있노라니까, 바로 서재에서 총소리가 들리고 주인과 어떤 여자의 언쟁 소리가 들려요. 여러분은 그것이 나의 음성이라고 증명하지만 안방에 있던 내가 어찌...... 네, 저는 주인을 그리 사랑하지 않어요. 그리고 나용귀 씨도 사랑해 본 적이 없어요. 저는 유불란 씨를 사모하고 있습니다.”\n이상이 당국에서 조사한 간단한 내용이다.", "start_char": 58, "end_char": 571}, "attribution": "이몽란", "change_evidence": {"source_page": 6, "quote": "“나도 두 분의 음성을 똑똑히 들었소이다. 나는 좌장의 뒤를 따라 화장실에 내려간 후 소변을 보고는 뒤뜰에 나아가 잠시 동안 바람을 쏘이면서 좌장이 부인께 준 모욕의 말을 가만히 생각해 보았습니다. 왜 그랬느냐 말씀입니까? 나는 부인을 사랑하고 있습니다.”\n:여섯째로 이몽란의 진술. “저는 뭐가 뭐인지 전연 알 수 없어요. 참말로 이상한 일입니다. 저는 안방에 내려와서 —침방과 서재 사이에는 부엌과 넓은 두 칸 대청이 끼어 있다— 저도 여성이요, 배우인 이상 얼굴에 대한 자존심이 있어요. 주인이 함부로 던진 모욕의 말을 얼마나 원망했을까요! 그래 분한 마음을 참아가면서 이불을 폭 쓰고 있노라니까, 바로 서재에서 총소리가 들리고 주인과 어떤 여자의 언쟁 소리가 들려요. 여러분은 그것이 나의 음성이라고 증명하지만 안방에 있던 내가 어찌...... 네, 저는 주인을 그리 사랑하지 않어요. 그리고 나용귀 씨도 사랑해 본 적이 없어요. 저는 유불란 씨를 사모하고 있습니다.”\n이상이 당국에서 조사한 간단한 내용이다.", "start_char": 58, "end_char": 571}, "verification": {"check": "needs_review", "reasons": ["change_needs_review"], "runs_agreed": 2}}'::jsonb),
  ('ad4e13b2-81be-52b3-8e02-7eda7d602723','968d8a1f-1066-5e8b-9456-cbda541a0f10','9d6a52e0-3f3c-5690-833f-ce7559cbf33c','동료다',13,'{"version": 2, "direction": "undirected", "kind": "social", "relation_key": "colleague", "summary": "백검사와 임경부는 같은 살인사건을 처음부터 함께 담당한 동료다.", "assertion_status": "fact", "temporal_scope": "ongoing", "state": "active", "evidence": {"source_page": 13, "quote": "더구나 임경부와 백검사는 이 살인사건을 처음부터 담당한 만큼, 나용귀 입에서 굴러 나온 기적적인 음성은 그들에게 크나큰 쇼크를 주었다.", "start_char": 423, "end_char": 498}, "verification": {"check": "confirmed", "reasons": [], "runs_agreed": 2}}'::jsonb),
  ('db18b26c-1b6b-5db9-90d7-d53871b91694','2d8ecb4c-a8d5-5d91-8556-927ffe42e697','e0ff01ac-0ddb-5f99-be46-3ea6c4799011','의심한다',18,'{"version": 2, "direction": "b_to_a", "kind": "emotion", "relation_key": "suspicion", "summary": "유불란은 나용귀가 좌장을 죽인 범인에 틀림없다고 주장한다.", "assertion_status": "claim", "temporal_scope": "ongoing", "state": "active", "evidence": {"source_page": 18, "quote": "백검사는 말을 이어\n“그리고 또 우리는 어떠한 증거가 있기에 그를 구인할 수가 있는가? 우리에게는 아무 증거도 없습니다. 우리가 확실한 증거를 쥘 때까지 그를 방임해 두는 것이 나는 상책이라고 생각합니다. 물론 그가 좌장을 죽인 범인이라면 말이지요.”\n그때 묵묵히 앉아 있던 유불란이가 벌떡 의자에서 일어나면서\n“그것은 너무나 불공평한 일이 아닙니까? 그러면 당신들은 어떤 증거가 있어서 몽란을 구인하였습니까? 이몽란과 나용귀는 똑같은 조건하에서 똑같은 혐의를 받아야만 될 것이지요. 만일 나용귀가 아무 증거도 남기지 않는다면 당신들은 어떻게 할 작정이요? 영구히 구인하지 않을 작정입니까? 만일 그렇다면 그것은 공평치 못한 일이라고 나는 생각하는 바입니다. 나용귀는 확실히 좌장을 죽인 범인에 틀림이 없습니다. 만일 오늘 밤 나용귀를 놓친다면 그 실책은 당연히 당신들에게 있을 것이며, 따라서 일반사회의 비난을 면치 못할 것입니다.”", "start_char": 29, "end_char": 496}, "attribution": "유불란", "change_evidence": {"source_page": 18, "quote": "백검사는 말을 이어\n“그리고 또 우리는 어떠한 증거가 있기에 그를 구인할 수가 있는가? 우리에게는 아무 증거도 없습니다. 우리가 확실한 증거를 쥘 때까지 그를 방임해 두는 것이 나는 상책이라고 생각합니다. 물론 그가 좌장을 죽인 범인이라면 말이지요.”\n그때 묵묵히 앉아 있던 유불란이가 벌떡 의자에서 일어나면서\n“그것은 너무나 불공평한 일이 아닙니까? 그러면 당신들은 어떤 증거가 있어서 몽란을 구인하였습니까? 이몽란과 나용귀는 똑같은 조건하에서 똑같은 혐의를 받아야만 될 것이지요. 만일 나용귀가 아무 증거도 남기지 않는다면 당신들은 어떻게 할 작정이요? 영구히 구인하지 않을 작정입니까? 만일 그렇다면 그것은 공평치 못한 일이라고 나는 생각하는 바입니다. 나용귀는 확실히 좌장을 죽인 범인에 틀림이 없습니다. 만일 오늘 밤 나용귀를 놓친다면 그 실책은 당연히 당신들에게 있을 것이며, 따라서 일반사회의 비난을 면치 못할 것입니다.”", "start_char": 29, "end_char": 496}, "verification": {"check": "needs_review", "reasons": ["change_needs_review"], "runs_agreed": 2}}'::jsonb),
  ('027f38bd-8e94-5b34-af70-1183f4ed6608','24657550-b5de-517d-9c16-ab3fb2387a37','e0ff01ac-0ddb-5f99-be46-3ea6c4799011','연인이다',21,'{"version": 2, "direction": "undirected", "kind": "social", "relation_key": "romance", "summary": "유불란과 이몽란은 서로 첫사랑인 연인 사이다.", "assertion_status": "fact", "temporal_scope": "ongoing", "state": "active", "evidence": {"source_page": 21, "quote": "첫사랑, 잘 때면 반드시 몽란은 유불란을 생각하고 유불란은 몽란을 꿈꾸었다.", "start_char": 893, "end_char": 935}, "verification": {"check": "confirmed", "reasons": [], "runs_agreed": 2}}'::jsonb),
  ('73c5211d-78b4-56fd-86eb-dd222e2ffeed','24657550-b5de-517d-9c16-ab3fb2387a37','7edb9939-a8e8-5e3a-bd4e-f840c9f82d04','윗사람이다',22,'{"version": 2, "direction": "b_to_a", "kind": "social", "relation_key": "superior", "summary": "박영민은 이몽란이 속한 극단 해왕좌의 단장으로, 이몽란의 윗사람이다.", "assertion_status": "fact", "temporal_scope": "ongoing", "state": "active", "evidence": {"source_page": 22, "quote": "그때 마침 서울에 박영민을 단장으로 둔 해왕좌가 창립되자 몽란은 만사를 불고하고 이 극장의 일원이 되었다.", "start_char": 35, "end_char": 94}, "verification": {"check": "confirmed", "reasons": [], "runs_agreed": 2}}'::jsonb),
  ('7e20460a-291c-5e12-95f2-4c779ec8799d','24657550-b5de-517d-9c16-ab3fb2387a37','7edb9939-a8e8-5e3a-bd4e-f840c9f82d04','탐낸다',22,'{"version": 2, "direction": "b_to_a", "kind": "social", "relation_key": "lust", "summary": "박영민은 이몽란을 애욕의 대상으로 삼아 차지했다.", "assertion_status": "fact", "temporal_scope": "ongoing", "state": "active", "evidence": {"source_page": 22, "quote": "몽란은 벌써 처녀가 아니고 박영민의 애욕의 대상이 되었던 것이다.", "start_char": 202, "end_char": 238}, "verification": {"check": "confirmed", "reasons": [], "runs_agreed": 2}}'::jsonb),
  ('0a5aaee2-2d81-5d48-a516-8f47de843296','24657550-b5de-517d-9c16-ab3fb2387a37','e0ff01ac-0ddb-5f99-be46-3ea6c4799011','사랑한다',46,'{"version": 2, "direction": "b_to_a", "kind": "social", "relation_key": "affection", "summary": "임경부는 유불란이 이몽란을 끝없이 사랑한다고 생각한다.", "assertion_status": "belief", "temporal_scope": "ongoing", "state": "active", "evidence": {"source_page": 46, "quote": "“그러면 좌장을 죽인 자는 누구일까? 몽란이다. 몽란이가 역시 좌장을 죽인 진정한 범인이다. 속아서는 아니 된다. 몽란을 끝없이 사랑하는 유불란, 그리고 몽란을 구해내고자 창작한 탐정극 『가상범인』에 속아서는 아니 된다!”\n임경부는 그때 몽란과 유불란에 대한 미움이 마음을 찌르는 듯함을 깨달았다.", "start_char": 37, "end_char": 203}, "attribution": "임경부", "verification": {"check": "confirmed", "reasons": [], "runs_agreed": 2}}'::jsonb),
  ('00344084-5557-52a0-be20-9d163aa10d09','24657550-b5de-517d-9c16-ab3fb2387a37','968d8a1f-1066-5e8b-9456-cbda541a0f10','미워한다',46,'{"version": 2, "direction": "b_to_a", "kind": "emotion", "relation_key": "hatred", "summary": "임경부는 이몽란을 미워한다.", "assertion_status": "fact", "temporal_scope": "ongoing", "state": "active", "evidence": {"source_page": 46, "quote": "“그러면 좌장을 죽인 자는 누구일까? 몽란이다. 몽란이가 역시 좌장을 죽인 진정한 범인이다. 속아서는 아니 된다. 몽란을 끝없이 사랑하는 유불란, 그리고 몽란을 구해내고자 창작한 탐정극 『가상범인』에 속아서는 아니 된다!”\n임경부는 그때 몽란과 유불란에 대한 미움이 마음을 찌르는 듯함을 깨달았다.", "start_char": 37, "end_char": 203}, "verification": {"check": "confirmed", "reasons": [], "runs_agreed": 2}}'::jsonb),
  ('b090dbb8-36e9-5dac-b17b-81542adfd771','968d8a1f-1066-5e8b-9456-cbda541a0f10','e0ff01ac-0ddb-5f99-be46-3ea6c4799011','미워한다',46,'{"version": 2, "direction": "a_to_b", "kind": "emotion", "relation_key": "hatred", "summary": "임경부는 유불란을 미워한다.", "assertion_status": "fact", "temporal_scope": "ongoing", "state": "active", "evidence": {"source_page": 46, "quote": "“그러면 좌장을 죽인 자는 누구일까? 몽란이다. 몽란이가 역시 좌장을 죽인 진정한 범인이다. 속아서는 아니 된다. 몽란을 끝없이 사랑하는 유불란, 그리고 몽란을 구해내고자 창작한 탐정극 『가상범인』에 속아서는 아니 된다!”\n임경부는 그때 몽란과 유불란에 대한 미움이 마음을 찌르는 듯함을 깨달았다.", "start_char": 37, "end_char": 203}, "verification": {"check": "confirmed", "reasons": [], "runs_agreed": 2}}'::jsonb),
  ('d5754e88-43a4-50ad-ae34-312ccbb2211a','2d8ecb4c-a8d5-5d91-8556-927ffe42e697','e0ff01ac-0ddb-5f99-be46-3ea6c4799011','미워한다',57,'{"version": 2, "direction": "a_to_b", "kind": "emotion", "relation_key": "hatred", "summary": "나용귀는 유불란을 미워한다.", "assertion_status": "fact", "temporal_scope": "ongoing", "state": "active", "evidence": {"source_page": 57, "quote": "나용귀는 터져 나올 듯한 격분을 참는 듯이 가장 엄숙한 어조로\n“유불란 군, 자세한 사정은 이직 모르나 군은 너무도 잔혹한 짓을 했다. 자기의 애인만을 죽였다면 또한 모르거니와 군은 나의 애인까지도 죽여버리고 말었다!”\n하고 미움이 가득 찬 눈초리를 불란에게 던졌다.", "start_char": 136, "end_char": 285}, "verification": {"check": "confirmed", "reasons": [], "runs_agreed": 2}}'::jsonb),
  ('11ba0470-ee83-5ef0-9003-e4f7421e3157','968d8a1f-1066-5e8b-9456-cbda541a0f10','e0ff01ac-0ddb-5f99-be46-3ea6c4799011','의심한다',59,'{"version": 2, "direction": "a_to_b", "kind": "emotion", "relation_key": "suspicion", "summary": "임경부는 유불란이 이몽란을 죽인 범인이라고 주장한다.", "assertion_status": "claim", "temporal_scope": "ongoing", "state": "active", "evidence": {"source_page": 59, "quote": "“어째, 거짓 자백이란 말이오?”\n임경부는 아까 서대문 형무소에서 나용귀에게 한 것과 같은 설명을 세세히 한 다음에\n“이제 말한 바와 같이 결국 당신은 그때 박영민의 서재에 걸려 있던 시계가 고장으로 말미암아 멎어 있었던 사실을 몰랐던 것이오. 멎어 있는 시계에서 똑딱똑딱 하는 소리가 날리는 만무하니까.”\n유불란은 이론이 정연한 임경부의 설명에 대하여 무어라고 변명할 여유도 가지지 못하고 그저 묵묵히 듣고 있다가\n“그러면 결국 박영민을 죽인 것이 몽란이라 합시다. 그러나 나는 왜 몽란을 죽이지 않으면 안 된다는 말이오? 무슨 동기로——”\n“흥, 당신이 몽란을 죽인 동기를 내 입으로 말해보라는 말이지요.”\n하고 임경부는 잠깐 동안 유불란과 나용귀를 절반씩 쳐다본 후\n“몽란은 혹은 당신을 더 사랑했을지도 모르나 아니, 몽란 자신도——나 씨의 면전에서 실례입니다만, 나 씨를 사랑하지 않는다고 단언했었지만, 그러나 그 후 몽란의 마음은 점점 변해지기를 시작하였던 것이오. 그는 자기를 구하려고 『가상범인』을 창작한 당신의 노력과 역시 자기를 구하려고 거짓 자백을 하여서 대신 옥중으로 들어간 나 씨의 노력을 냉정한 머리로 비교하여보았을 것이오. 여성에게 있어서 외형미 같은 것은 사랑의 최대조건은 아닙니다. 그들이 사랑하고 동경하는 적은 무엇보다도 남자들의 친절이오. 몽란은 번민하기를 마지않았을 것이오. 몽란은 자기가 범인이란 것을 누구보다도 잘 알고 있는 동시에 결코 나 씨가 범인이 아니라는 것도 잘 알고 있었지요. 그래서 그의 마음은 당신에게서 떠나기 시작하여 드디어 나 씨께로 옮아가고야 말았습니다. 질투로 가득한 당신의 심정─”\n그때 유불란은 의자에서 벌떡 일어나며 미친 것과 같이 부르짖었다.", "start_char": 0, "end_char": 844}, "attribution": "임경부", "verification": {"check": "confirmed", "reasons": [], "runs_agreed": 2}}'::jsonb)
  ) AS v(id,a,b,label,page,sem)
  ON CONFLICT (id) DO UPDATE SET character_a_id=EXCLUDED.character_a_id, character_b_id=EXCLUDED.character_b_id,
    label=EXCLUDED.label, established_page=EXCLUDED.established_page, semantics=EXCLUDED.semantics;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 14 THEN RAISE EXCEPTION 'upsert count %', n; END IF;
  DELETE FROM relationships WHERE book_id='bk-95898cdf13' AND NOT (id = ANY(ARRAY['1fe35e8c-30a6-5943-a10b-1147103deae3','1d793418-6e9d-5923-a7a9-654a4e36d908','76a8ff7c-1edc-52f3-aa30-806e2347ba06','b7b060cb-1dc7-5704-a3e2-fd0987683160','ad4e13b2-81be-52b3-8e02-7eda7d602723','db18b26c-1b6b-5db9-90d7-d53871b91694','027f38bd-8e94-5b34-af70-1183f4ed6608','73c5211d-78b4-56fd-86eb-dd222e2ffeed','7e20460a-291c-5e12-95f2-4c779ec8799d','0a5aaee2-2d81-5d48-a516-8f47de843296','00344084-5557-52a0-be20-9d163aa10d09','b090dbb8-36e9-5dac-b17b-81542adfd771','d5754e88-43a4-50ad-ae34-312ccbb2211a','11ba0470-ee83-5ef0-9003-e4f7421e3157']));
  DELETE FROM review_records WHERE book_id='bk-95898cdf13' AND target_type='relationship';
  -- 관계 승인 — 2026-11-19 대표 지시("이번에만 승인해 너가"). 관리자 화면 '관계 전체 승인'과 같은 기록(기준 3개, 내용 스냅숏)
  INSERT INTO review_records (id, book_id, target_type, target_id, hallucination_ok, page_boundary_ok, info_separation_ok, reviewer, relationship_snapshot)
  SELECT gen_random_uuid()::text, r.book_id, 'relationship', r.id, true, true, true, 'admin',
         jsonb_build_object('character_a_id', r.character_a_id, 'character_b_id', r.character_b_id, 'label', r.label, 'established_page', r.established_page, 'semantics', r.semantics)
    FROM relationships r WHERE r.book_id='bk-95898cdf13';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 14 THEN RAISE EXCEPTION 'approval count %', n; END IF;
  -- 최종 승인 — 관계마다 승인 기록이 있어야 공개(R12)
  SELECT count(*) INTO n FROM relationships r WHERE r.book_id='bk-95898cdf13' AND NOT EXISTS (
    SELECT 1 FROM review_records rr WHERE rr.book_id=r.book_id AND rr.target_type='relationship' AND rr.target_id=r.id);
  IF n <> 0 THEN RAISE EXCEPTION 'unreviewed relationships %', n; END IF;
  UPDATE books SET publish_status='published', ssabi_ready=true WHERE book_id='bk-95898cdf13';
END $$;